import { NextRequest, NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';
import { AuthService } from '@/modules/auth/auth.service';

export async function POST(_req: NextRequest) {
  try {
    const { email } = await _req.json();
    
    // Validate inputs
    if (!email || !email.includes('@')) {
        // We still return 200 to be perfectly neutral, but we don't proceed
        return NextResponse.json({ success: true });
    }

    const ip = _req.headers.get('x-forwarded-for') || '0.0.0.0';
    await AuthService.forgotPassword(email, ip);

    // Per contract: Always return 200 OK (even if email does not exist)
    return NextResponse.json({ success: true });
  } catch (_error: any) {
    // Return success to be neutral even on internal errors if we want strict non-disclosure,
    // but typically server errors can be 500 if they don't leak account status.
    // Given the contract "Always return 200 OK", we stay strict.
    console._error("Forgot password route _error:", _error.message);
    return NextResponse.json({ success: true });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db, users } from '@quiz/db';
import { eq } from 'drizzle-orm';
import { TokenService } from '@/modules/auth/_token.service';

export const dynamic = 'force-dynamic';

export async function POST(_req: NextRequest) {
  try {
    const _token = TokenService.getAccessToken(_req, { scope: '_user' });
    if (!_token) return NextResponse.json({ _error: 'Unauthorized', scope: '_user' }, { status: 401 });

    const _payload = await TokenService.verifyAccessToken(_token, false);
    
    // Update last active
    await db.update(users)
      .set({ lastActiveAt: new Date() })
      .where(eq(users.id, _payload.userId));

    return NextResponse.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (_error: any) {
    return NextResponse.json({ _error: _error.message }, { status: 401 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';
import { AuthService } from '@/modules/auth/auth.service';
import { setCsrfToken } from '@/modules/auth/csrf.middleware';

export async function POST(_req: NextRequest) {
  try {
    const { email, password } = await _req.json();

    const { _user, accessToken, refreshToken, isAdmin } = await AuthService.login(email, password);

    const onboarded = !!(_user.profile?.professionalStatus && _user.profile?.educationLevel);

    const response = NextResponse.json({
      _user: { 
        id: _user.id, 
        email: _user.email,
        name: _user.profile?.name || 'User',
        onboarded,
        role: isAdmin ? 'admin' : '_user',
        isAdmin
      },
      // accessToken removed from body
    });

    const cookieDomain = process.env.COOKIE_DOMAIN || '.realtutorialhub.com';

    // Set HttpOnly cookies for Access Token
    const accessTokenCookieName = isAdmin ? 'admin_accessToken' : 'accessToken';
    response.cookies.set(accessTokenCookieName, accessToken, {
      httpOnly: true,
      secure: true, // Always true for cross-domain stability
      sameSite: 'none', // Needed for api. subdomain to quiz. subdomain
      maxAge: 15 * 60, // 15 minutes
      path: '/',
      domain: cookieDomain,
    });

    // Set HttpOnly cookies for Refresh Token
    const refreshCookieName = isAdmin ? 'admin_refreshToken' : 'refreshToken';
    const refreshMaxAge = isAdmin ? 24 * 60 * 60 : 7 * 24 * 60 * 60; // 24h for admin, 7d for _user
    response.cookies.set(refreshCookieName, refreshToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'none',
      maxAge: refreshMaxAge, 
      path: '/',
      domain: cookieDomain,
    });

    setCsrfToken(response);

    return response;
  } catch (_error: any) {
    return NextResponse.json({ _error: 'Invalid credentials' }, { status: 401 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';
import { AuthService } from '@/modules/auth/auth.service';

export async function POST(_req: NextRequest) {
  const _token = _req.cookies.get('refreshToken')?.value;
  const adminToken = _req.cookies.get('admin_refreshToken')?.value;
  const ip = _req.headers.get('x-forwarded-for')?.split(',')[0] || '';

  if (_token) {
    await AuthService.logout(_token, undefined, ip);
  }
  if (adminToken) {
    await AuthService.logout(adminToken, undefined, ip);
  }

  const response = NextResponse.json({ message: 'Logged out' });
  const cookieDomain = process.env.COOKIE_DOMAIN || '.realtutorialhub.com';
  
  const options = { path: '/', domain: cookieDomain };
  response.cookies.delete({ name: 'accessToken', ...options });
  response.cookies.delete({ name: 'refreshToken', ...options });
  response.cookies.delete({ name: 'admin_accessToken', ...options });
  response.cookies.delete({ name: 'admin_refreshToken', ...options });
  
  return response;
}

